1	syntax = "proto3";
2	
3	package memos.store;
4	
5	import "google/protobuf/timestamp.proto";
6	import "google/type/color.proto";
7	
8	option go_package = "gen/store";
9	
10	message UserSetting {
11	  enum Key {
12	    KEY_UNSPECIFIED = 0;
13	    // General user settings.
14	    GENERAL = 1;
15	    // The shortcuts of the user.
16	    SHORTCUTS = 4;
17	    // The webhooks of the user.
18	    WEBHOOKS = 5;
19	    // Refresh tokens for the user.
20	    REFRESH_TOKENS = 6;
21	    // Personal access tokens for the user.
22	    PERSONAL_ACCESS_TOKENS = 7;
23	    // Per-user tag metadata.
24	    TAGS = 8;
25	  }
26	
27	  int32 user_id = 1;
28	
29	  Key key = 2;
30	  oneof value {
31	    GeneralUserSetting general = 3;
32	    ShortcutsUserSetting shortcuts = 6;
33	    WebhooksUserSetting webhooks = 7;
34	    RefreshTokensUserSetting refresh_tokens = 8;
35	    PersonalAccessTokensUserSetting personal_access_tokens = 9;
36	    TagsUserSetting tags = 10;
37	  }
38	}
39	
40	message GeneralUserSetting {
41	  // The user's locale.
42	  string locale = 1;
43	  // The user's memo visibility setting.
44	  string memo_visibility = 2;
45	  // The user's theme preference.
46	  // This references a CSS file in the web/public/themes/ directory.
47	  string theme = 3;
48	}
49	
50	message UserTagMetadata {
51	  // Optional background color for the tag label.
52	  // When unset, the default tag color is used.
53	  google.type.Color background_color = 1;
54	  // Whether memos with this tag should have their content blurred.
55	  bool blur_content = 2;
56	}
57	
58	message TagsUserSetting {
59	  // Map of tag name pattern to tag metadata.
60	  // Each key is treated as an anchored regular expression (^pattern$),
61	  // so a single entry like "project/.*" matches all tags under that prefix.
62	  // Exact tag names are also valid.
63	  map<string, UserTagMetadata> tags = 1;
64	}
65	
66	message RefreshTokensUserSetting {
67	  message RefreshToken {
68	    // Unique identifier (matches 'tid' claim in JWT)
69	    string token_id = 1;
70	    // When the token expires
71	    google.protobuf.Timestamp expires_at = 2;
72	    // When the token was created
73	    google.protobuf.Timestamp created_at = 3;
74	    // Client information for session management UI
75	    ClientInfo client_info = 4;
76	    // Optional description
77	    string description = 5;
78	  }
79	
80	  message ClientInfo {
81	    // User agent string of the client.
82	    string user_agent = 1;
83	    // IP address of the client.
84	    string ip_address = 2;
85	    // Optional. Device type (e.g., "mobile", "desktop", "tablet").
86	    string device_type = 3;
87	    // Optional. Operating system (e.g., "iOS 17.0", "Windows 11").
88	    string os = 4;
89	    // Optional. Browser name and version (e.g., "Chrome 119.0").
90	    string browser = 5;
91	  }
92	
93	  repeated RefreshToken refresh_tokens = 1;
94	}
95	
96	message PersonalAccessTokensUserSetting {
97	  message PersonalAccessToken {
98	    // Unique identifier for this token
99	    string token_id = 1;
100	    // SHA-256 hash of the actual token
101	    string token_hash = 2;
102	    // User-provided description
103	    string description = 3;
104	    // When the token expires (null = never)
105	    google.protobuf.Timestamp expires_at = 4;
106	    // When the token was created
107	    google.protobuf.Timestamp created_at = 5;
108	    // When the token was last used
109	    google.protobuf.Timestamp last_used_at = 6;
110	  }
111	  repeated PersonalAccessToken tokens = 1;
112	}
113	
114	message ShortcutsUserSetting {
115	  message Shortcut {
116	    string id = 1;
117	    string title = 2;
118	    string filter = 3;
119	  }
120	  repeated Shortcut shortcuts = 1;
121	}
122	
123	message WebhooksUserSetting {
124	  message Webhook {
125	    // Unique identifier for the webhook
126	    string id = 1;
127	    // Descriptive title for the webhook
128	    string title = 2;
129	    // The webhook URL endpoint
130	    string url = 3;
131	    // Optional signing secret for webhook authentication.
132	    string signing_secret = 4;
133	  }
134	  repeated Webhook webhooks = 1;
135	}
